108	    /**
109	     * Update the data for the population line chart. This is called
110	     * periodically.
111	     */
112	    private void updatePopulationLineChart()
113	    {
114	        // Reset if necessary:
115	        if (Simulator.resetStatisticsView)
116	        {
117	            resetPopulationLineChart();
118	            Simulator.resetStatisticsView = false;
119	        }
120	        
121	        // Guard statement: Don't continue with this if the day
122	        // hasn't changed since the last update:
123	        if (lastDayRecorded == TimeSystem.getCurrentDay()) return;
124	        
125	        // Iterate through each counter in FieldStats:
126	        Field field = Simulator.getCurrentField();
127	        Map<Class<?>, Counter> counters = FieldStats.getCounters(field);
128	        
129	        for (Class<?> key : counters.keySet())
130	        {
131	            Counter counter = counters.get(key);
132	            
133	            // Get the new data to add to the XYSeries:
134	            Data<Number, Number> newData = new Data<>(TimeSystem.getCurrentDay(), counter.getCount());
135	            
136	            // Create a new XYSeries for this actor if there is none already:
137	            if (!actorXYSeries.containsKey(key))
138	            {
139	                Series<Number, Number> series = new Series<>();
140	                series.setName(counter.getName());
141	                
142	                lineChart.getData().add(series);
143	                
144	                actorXYSeries.put(key, series);
145	            }
146	            
147	            // Update the XYSeries for this Actor:
148	            Series<Number, Number> series = actorXYSeries.get(key);
149	            series.getData().add(newData); 
150	            
151	            // Update the highest population if necessary:
152	            if (counter.getCount() > highestPopulation) highestPopulation = counter.getCount();
153	        }
154	        
155	        // Set the new last day recorded:
156	        lastDayRecorded = TimeSystem.getCurrentDay();
157	        
158	        // Set the upper bounds for each of the axes:
159	        xAxis.setUpperBound(TimeSystem.getCurrentDay());
160	        yAxis.setUpperBound(highestPopulation);
161	    }
